"""03/11/2026: sessão-modelo. Caso inventado, materiais antes das perguntas.
A alternativa escrita substitui o vídeo ainda não visionado. Apenas a conclusão usa papel.
"""
import json
from pathlib import Path
ONU='https://unric.org/pt/declaracao-universal-dos-direitos-humanos/'
FONTE=f'<p class="credito">Fonte: <a href="{ONU}">Nações Unidas, Declaração Universal</a>. Excertos.</p>'
def ler(rot,titulo,html,**kw):return dict(t='ler',rot=rot,titulo=titulo,html=html,**kw)
def escolha(p,p2,o,c,f,fe):return dict(t='escolha',p=p,p2=p2,o=o,c=c,f=f,fe=fe)
def vf(p,p2,v,f,fe):return dict(t='vf',p=p,p2=p2,v=v,f=f,fe=fe)
def pares(p,p2,ps,f,fe):return dict(t='emparelhar',p=p,p2=p2,pares=ps,f=f,fe=fe)
def sub(p,p2,frase,certas,f):return dict(t='sublinhar',p=p,p2=p2,frase=frase,certas=certas,f=f)
def ordem(p,p2,passos,f,fe):return dict(t='ordenar',p=p,p2=p2,passos=passos,f=f,fe=fe)
cartoes=[
ler('Abre','Uma fotografia no grupo','<p class="pergunta-c">Que provas precisas de observar antes de decidir?</p><p>Caso inventado. Às 8h20, uma aluna é fotografada a dormir no autocarro. A imagem chega ao grupo da turma. Ninguém lhe perguntou se queria ser fotografada ou se aceitava a partilha.</p><p>Antes de decidir, observa uma fotografia, lê excertos da Declaração Universal e distingue o que sabes do que falta saber. No fim, escreves apenas três linhas em papel.</p>'),
ler('Olha','Um documento nas mãos', '<figure class="fig inteiro"><span class="moldura"><img src="../../img/cidadania/eleanor-roosevelt-dudh-1949.webp" alt="Eleanor Roosevelt segura com ambas as mãos um cartaz inclinado, com o emblema da ONU, o título inglês da Declaração Universal e várias colunas de texto."></span><figcaption>Eleanor Roosevelt com a Declaração Universal, Lake Success, novembro de 1949. Fotógrafo não identificado. FDR Presidential Library &amp; Museum, 64-165. <a href="https://www.flickr.com/photos/fdrlibrary/27758131387/">Fonte</a>; <a href="https://creativecommons.org/licenses/by/2.0/">CC BY 2.0</a>. Reprodução em WebP.</figcaption></figure><p>Observa o que as mãos seguram e a disposição do texto. A fotografia permite ler o título; não precisamos de decifrar os artigos dentro da imagem.</p>'),
escolha('Que elemento consegues observar diretamente na fotografia?','O que está visível, sem ser preciso acrescentar uma interpretação?', ['O documento apresenta várias colunas de texto.','O documento foi escrito pela mulher retratada.','O documento convenceu todas as pessoas da sala.'],0,'Vês colunas de texto no cartaz. A fotografia não mostra quem escreveu o documento nem o que pensaram outras pessoas.',['','Segurar um cartaz não prova a autoria do texto. Procura um elemento que esteja visível.','A fotografia não permite saber o que pensaram as pessoas que a viram.']),
sub('No título transcrito, seleciona as duas palavras que identificam de quem são os direitos.','Que duas palavras do título significam «direitos humanos»?', 'The Universal Declaration of Human Rights',[4,5],'«Human Rights» significa «direitos humanos». «Universal» indica o alcance pretendido do documento.'),
ler('Lê','Três excertos para usar', '<p><b>Artigo 1.º:</b> «Todos os seres humanos nascem livres e iguais em dignidade e em direitos.»</p><p><b>Artigo 12.º:</b> «Ninguém sofrerá intromissões arbitrárias na sua vida privada».</p><p><b>Artigo 19.º:</b> «Todo o indivíduo tem direito à liberdade de opinião e de expressão».</p><p>São excertos, não os artigos completos. Guarda a diferença entre dignidade, vida privada e expressão.</p>'+FONTE),
pares('Liga cada preocupação ao excerto que a menciona.','Que excerto fala diretamente de cada preocupação?', [['Uma pessoa ser tratada como menos digna','Artigo 1.º: igualdade em dignidade'],['Uma intromissão arbitrária na vida privada','Artigo 12.º: vida privada'],['Uma pessoa poder dar a sua opinião','Artigo 19.º: opinião e expressão']], 'A ligação segue as palavras dos excertos. Identificar um direito não basta para resolver todas as situações em que ele intervém.','Volta às palavras «dignidade», «vida privada» e «opinião». Cada uma aparece num excerto diferente.'),
vf('O excerto do artigo 12.º qualifica as intromissões de «arbitrárias».','A palavra «arbitrárias» faz parte do excerto sobre a vida privada.',True,'O qualificativo está no texto. O exercício pede leitura exata, não a decisão jurídica sobre uma fotografia.','Relê o artigo 12.º: o texto não diz apenas «intromissões»; acrescenta «arbitrárias».'),
escolha('Que prova textual apoia a ideia de que a dignidade não depende da popularidade?','Que passagem inclui também uma pessoa que quase ninguém conhece?', ['«Todos os seres humanos nascem livres e iguais»','«direito à liberdade de opinião e de expressão»','«intromissões arbitrárias na sua vida privada»'],0,'«Todos os seres humanos» não limita a dignidade às pessoas populares. A conclusão usa o alcance dessas palavras.',['','O excerto sobre opinião refere outra proteção. A pergunta pede as palavras que incluem todas as pessoas.','Este fragmento pertence à proteção da vida privada. Procura a expressão que inclui todos.']),
ler('Lê','Uma finalidade, dois meios','<p>No preâmbulo, a Assembleia Geral apresenta a Declaração como um «ideal comum a atingir por todos os povos e todas as nações».</p><p>O texto pede que se desenvolva o respeito pelos direitos «pelo ensino e pela educação» e que se promova o seu reconhecimento e aplicação.</p><p>O alcance é universal; o ensino e a educação são meios mencionados. A formulação de um ideal não prova, por si, que esse ideal já se cumpra.</p>'+FONTE),
ordem('Reconstrói a ordem destas três ideias na leitura anterior.','Segue a sequência apresentada no apoio escrito.', ['Um ideal comum para todos os povos e nações.','O ensino e a educação desenvolvem o respeito.','Promover o reconhecimento e a aplicação dos direitos.'], 'A leitura começa pelo ideal, indica o ensino e a educação e termina no reconhecimento e na aplicação. É a ordem deste texto, não uma cronologia histórica.','Volta ao apoio: procura primeiro a finalidade e depois os meios e o resultado pretendido.'),
escolha('Que meio é nomeado no apoio para desenvolver o respeito pelos direitos?','Que meio aparece nas palavras do preâmbulo que acabaste de ler?', ['O ensino e a educação das pessoas.','A divulgação e a leitura de cartazes.','A discussão e a aprovação de normas.'],0,'O apoio cita «pelo ensino e pela educação». As outras propostas não estão no excerto.',['','A fotografia mostra um cartaz, mas esse não é o meio mencionado no excerto. Localiza as palavras que vêm depois de «pelo».','O excerto pede desenvolvimento do respeito através do ensino e da educação.']),
vf('O apoio demonstra que todos os direitos já são respeitados em todos os países.','Apresentar um ideal comum prova que ele já se cumpre em todo o lado.',False,'O apoio enuncia um ideal a atingir e ações para o promover. Isso não demonstra cumprimento universal.','Distingue uma finalidade da prova de que ela foi alcançada. O excerto apresenta a finalidade.'),
sub('Seleciona as duas palavras que mostram que o ideal é uma finalidade ainda a alcançar.','Que duas palavras distinguem a finalidade de um resultado já conseguido?', 'Um ideal comum a atingir por todos os povos e todas as nações.',[3,4],'«A atingir» apresenta uma finalidade. Não é uma afirmação de que todos os povos já a tenham alcançado.'),
ler('Na aula','Volta ao caso','<p>A fotografia foi partilhada sem perguntar à aluna. Quem a publicou diz que foi uma brincadeira. A aluna pede que a retirem e não a voltem a partilhar.</p><p>Conheces estas posições, mas não sabes quem recebeu ou guardou a imagem. Faz os próximos exercícios individualmente. Compara os factos com os excertos; revê os retornos antes de escrever a conclusão final.</p><p>O caso é inventado. Não uses fotografias nem histórias identificáveis de colegas.</p>'),
escolha('Que pergunta esclarece uma dúvida ainda aberta neste caso?','Que informação falta obter antes de avaliar o alcance da partilha?', ['Quem recebeu ou guardou a fotografia?','Quem aparece a dormir na fotografia?','Quem pediu que retirassem a fotografia?'],0,'Ainda não sabemos quem recebeu ou guardou a imagem. As outras perguntas retomam factos já apresentados.',['','O caso já identifica quem aparece: a aluna fotografada no autocarro.','O caso diz que a aluna pediu a retirada. A dúvida aberta diz respeito à circulação da imagem.']),
pares('Relaciona cada frase com o apoio que permite sustentá-la.','Que material sustenta cada afirmação, sem acrescentar factos?', [['A partilha ocorreu sem perguntar à aluna.','O relato do caso inventado.'],['A dignidade é atribuída a todos os seres humanos.','O excerto do artigo 1.º.'],['A vida privada recebe proteção no documento.','O excerto do artigo 12.º.']], 'O relato fornece factos do caso; os artigos fornecem princípios para pensar esses factos. A fotografia de Roosevelt não prova o que aconteceu no autocarro.','Pergunta se a frase descreve o caso ou retoma palavras de um artigo. Não uses a fotografia como prova de um acontecimento diferente.'),
ordem('Organiza a justificação para que cada passo se apoie no anterior.','Começa pelo que aconteceu e termina no que ainda falta saber.', ['Facto: a imagem foi partilhada sem perguntar.','Fonte: o artigo 12.º menciona a vida privada.','Aplicação: há uma preocupação com a exposição da aluna.','Limite: falta saber quem recebeu ou guardou a imagem.'], 'A sequência distingue facto, fonte, aplicação e limite. Não transforma um excerto num veredito automático.','Identifica o facto antes de lhe aplicar a fonte. A dúvida deve aparecer depois da conclusão provisória.'),
escolha('Que conclusão distingue melhor uma razão de uma certeza que ainda não temos?','Escolhe a conclusão que usa o artigo sem inventar o alcance da circulação.', ['O artigo apoia a preocupação; falta conhecer a circulação.','O artigo prova a intenção; falta conhecer quem a publicou.','O artigo garante a remoção; falta conhecer quem a guardou.'],0,'O artigo ajuda a pensar a vida privada. Não prova intenções nem garante que uma imagem seja apagada de todos os aparelhos.',['','O artigo não revela a intenção de quem publicou. O caso também já apresenta essa pessoa pela sua ação.','Uma norma não garante, por si, a remoção de cópias. Falta conhecer a circulação.']),
vf('A análise deste caso prova que qualquer fotografia de uma pessoa é sempre proibida.','Deste caso podemos concluir uma proibição absoluta de todas as fotografias de pessoas.',False,'A conclusão ultrapassa o caso e os excertos. Uma justificação deve indicar o que sabe e os seus limites.','O exercício trata de uma partilha concreta sem perguntar. Não fornece prova para uma regra absoluta sobre todas as fotografias.'),
ler('Para levar','Três linhas, uma conclusão','<p>Escreve individualmente, em papel:</p><ol><li>A tua conclusão provisória sobre a partilha deste caso.</li><li>Uma prova concreta do relato e uma expressão do artigo que usaste.</li><li>Uma dúvida que ainda precisa de resposta.</li></ol><p>Confere: separaste factos e interpretações? A prova sustenta a conclusão? Evitaste transformar este caso numa regra absoluta?</p>',escuro=True),
]
dados=dict(id='cidadania-m1-s01',chave='epi-cid-m1-s01',versao='2026-11-03-modelo-1',marca='CD',titulo='Sessão 01: Uma fotografia no grupo',h1='Humanos, sessão 01: Uma fotografia no grupo',modulo=dict(n=1,nome='Humanos',url='https://pedrohfernandes-klk.github.io/lente/cidadania/piloto/m1/'),saida='demonstracoes/cidadania-sessao-modelo/index.html',piloto=True,modelo=True,ampliar=True,seguinte='../../cidadania/piloto/m1/',seguinteRotulo='Voltar ao módulo',fontes='Declaração Universal dos Direitos Humanos (Nações Unidas, 1948), preâmbulo e excertos dos artigos 1.º, 12.º e 19.º, transcrição portuguesa do UNRIC. Fotografia: Eleanor Roosevelt com a Declaração Universal, Lake Success, novembro de 1949, FDR Presidential Library & Museum, 64-165, CC BY 2.0. Fotógrafo não identificado. O caso e as propostas de resposta são construções pedagógicas.',cartoes=cartoes)
p=Path(__file__).with_suffix('.json');p.write_text(json.dumps(dados,ensure_ascii=False,indent=1)+'\n',encoding='utf-8')
print(len(cartoes),'cartões;',sum(c['t']!='ler' for c in cartoes),'de fazer')
